import { ProjectRepository } from '../domain/ProjectRepository';
import { ProjectEntity } from '../domain/Project';
import { CreateProjectRequest, CreateProjectResponse } from './dtos';

export class CreateProjectUseCase {
  constructor(private projectRepository: ProjectRepository) {}

  execute(request: CreateProjectRequest): CreateProjectResponse {
    const projectId = Math.random().toString(36).substring(2, 11);
    const project = new ProjectEntity(projectId, request.name);
    this.projectRepository.save(project);

    return {
      id: project.id,
      name: project.name,
    };
  }
}

